import full = require( './index' );


// TESTS //

// The function returns an ndarray...
{
	full( 'float64', [ 2, 2 ], 'row-major', 10.0 ); // $ExpectType float64ndarray
	full( 'float32', [ 2, 2 ], 'row-major', 10.0 ); // $ExpectType float32ndarray
	full( 'complex128', [ 2, 2 ], 'row-major', 10.0 ); // $ExpectType complex128ndarray
	full( 'complex64', [ 2, 2 ], 'row-major', 10.0 ); // $ExpectType complex64ndarray
	full( 'int32', [ 2, 2 ], 'row-major', 10.0 ); // $ExpectType int32ndarray
	full( 'int16', [ 2, 2 ], 'row-major', 10.0 ); // $ExpectType int16ndarray
	full( 'int8', [ 2, 2 ], 'row-major', 10.0 ); // $ExpectType int8ndarray
	full( 'uint32', [ 2, 2 ], 'row-major', 10.0 ); // $ExpectType uint32ndarray
	full( 'uint16', [ 2, 2 ], 'row-major', 10.0 ); // $ExpectType uint16ndarray
	full( 'uint8', [ 2, 2 ], 'row-major', 10.0 ); // $ExpectType uint8ndarray
	full( 'uint8c', [ 2, 2 ], 'row-major', 10.0 ); // $ExpectType uint8cndarray
	full( 'bool', [ 2, 2 ], 'row-major', true ); // $ExpectType boolndarray
	full( 'generic', [ 2, 2 ], 'row-major', 10.0 ); // $ExpectType genericndarray<number>

	full( 'float64', [ 2, 2 ], 'column-major', 10.0 ); // $ExpectType float64ndarray
	full( 'float32', [ 2, 2 ], 'column-major', 10.0 ); // $ExpectType float32ndarray
	full( 'complex128', [ 2, 2 ], 'column-major', 10.0 ); // $ExpectType complex128ndarray
	full( 'complex64', [ 2, 2 ], 'column-major', 10.0 ); // $ExpectType complex64ndarray
	full( 'int32', [ 2, 2 ], 'column-major', 10.0 ); // $ExpectType int32ndarray
	full( 'int16', [ 2, 2 ], 'column-major', 10.0 ); // $ExpectType int16ndarray
	full( 'int8', [ 2, 2 ], 'column-major', 10.0 ); // $ExpectType int8ndarray
	full( 'uint32', [ 2, 2 ], 'column-major', 10.0 ); // $ExpectType uint32ndarray
	full( 'uint16', [ 2, 2 ], 'column-major', 10.0 ); // $ExpectType uint16ndarray
	full( 'uint8', [ 2, 2 ], 'column-major', 10.0 ); // $ExpectType uint8ndarray
	full( 'uint8c', [ 2, 2 ], 'column-major', 10.0 ); // $ExpectType uint8cndarray
	full( 'bool', [ 2, 2 ], 'column-major', true ); // $ExpectType boolndarray
	full( 'generic', [ 2, 2 ], 'column-major', 10.0 ); // $ExpectType genericndarray<number>
}

// The compiler throws an error if the function is provided a first argument which is an unrecognized/unsupported data type...
{
	full( '10', [ 2, 2 ], 'row-major', 10.0 ); // $ExpectError
	full( 10, [ 2, 2 ], 'row-major', 10.0 ); // $ExpectError
	full( false, [ 2, 2 ], 'row-major', 10.0 ); // $ExpectError
	full( true, [ 2, 2 ], 'row-major', 10.0 ); // $ExpectError
	full( null, [ 2, 2 ], 'row-major', 10.0 ); // $ExpectError
	full( [], [ 2, 2 ], 'row-major', 10.0 ); // $ExpectError
	full( {}, [ 2, 2 ], 'row-major', 10.0 ); // $ExpectError
	full( ( x: number ): number => x, [ 2, 2 ], 'row-major', 10.0 ); // $ExpectError
}

// The compiler throws an error if the function is not provided a valid shape for the second argument...
{
	full( 'float32', '5', 'row-major', 10.0 ); // $ExpectError
	full( 'float32', false, 'row-major', 10.0 ); // $ExpectError
	full( 'float32', true, 'row-major', 10.0 ); // $ExpectError
	full( 'float32', null, 'row-major', 10.0 ); // $ExpectError
	full( 'float32', undefined, 'row-major', 10.0 ); // $ExpectError
	full( 'float32', [ '5' ], 'row-major', 10.0 ); // $ExpectError
	full( 'float32', {}, 'row-major', 10.0 ); // $ExpectError
	full( 'float32', ( x: number ): number => x, 'row-major', 10.0 ); // $ExpectError
}

// The compiler throws an error if the function is not provided a valid order for the third argument...
{
	full( 'float32', [ 2, 2 ], '5', 10.0 ); // $ExpectError
	full( 'float32', [ 2, 2 ], false, 10.0 ); // $ExpectError
	full( 'float32', [ 2, 2 ], true, 10.0 ); // $ExpectError
	full( 'float32', [ 2, 2 ], null, 10.0 ); // $ExpectError
	full( 'float32', [ 2, 2 ], undefined, 10.0 ); // $ExpectError
	full( 'float32', [ 2, 2 ], [ '5' ], 10.0 ); // $ExpectError
	full( 'float32', [ 2, 2 ], {}, 10.0 ); // $ExpectError
	full( 'float32', [ 2, 2 ], ( x: number ): number => x, 10.0 ); // $ExpectError
}

// The compiler throws an error if the function is not provided a valid value for the fourth argument...
{
	full( 'float32', [ 2, 2 ], 'row-major', '5' ); // $ExpectError
	full( 'float32', [ 2, 2 ], 'row-major', false ); // $ExpectError
	full( 'float32', [ 2, 2 ], 'row-major', true ); // $ExpectError
	full( 'float32', [ 2, 2 ], 'row-major', null ); // $ExpectError
	full( 'float32', [ 2, 2 ], 'row-major', undefined ); // $ExpectError
	full( 'float32', [ 2, 2 ], 'row-major', [ '5' ] ); // $ExpectError
	full( 'float32', [ 2, 2 ], 'row-major', {} ); // $ExpectError
	full( 'float32', [ 2, 2 ], 'row-major', ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	full( 'float64' ); // $ExpectError
	full( 'float64', [ 2, 2 ] ); // $ExpectError
	full( 'float64', [ 2, 2 ], 'row-major' ); // $ExpectError
}
